// LEDGER-RETENTION variant of ../solana-unified-wallet-v1/managed-validator.mjs (frozen, untouched), generated by make_validator_ledger.py: the validator keeps its whole ledger.
// Full connected-wallet qualification bootstrap. New run only; never changes a live publication run.
// Owned local validator bootstrap. Only synthetic ADMIN setup is signed here;
// every wallet signature must originate in the browser, never this process.
import {mkdtemp,mkdir,writeFile,readFile,open,rm} from 'node:fs/promises';
import {spawn,execFileSync} from 'node:child_process';
import net from 'node:net';
import {hostLease} from '../solana-unified-wallet-v1/host-lease.mjs';
import assert from 'node:assert/strict';
import {fileURLToPath} from 'node:url';
import {b58,key,un58,sha,u32} from '../solana-beta-withdraw-v1/runtime-helpers.mjs';
import {signedTransaction} from '../solana-beta-withdraw-v1/publisher/transport.mjs';
const root=fileURLToPath(new URL('../solana-chrome-wallet-v1/',import.meta.url)),base=fileURLToPath(new URL('../solana-beta-withdraw-v1/',import.meta.url));
const out=process.argv[2],evidenceRoot=root+'evidence/';
assert.ok(typeof out==='string' && out.startsWith(evidenceRoot)
  && /^(browser-connected-wallet|installed-connected)-[0-9]+$/.test(out.slice(evidenceRoot.length)));
const fixtureBin=fileURLToPath(new URL('../solana-token-custody-v1/target/debug/settlement-fixtures',import.meta.url));
const validator='<HOME>/.local/share/solana/install/releases/3.1.10/solana-release/bin/solana-test-validator';
const elf=base+'sbf-bin/zk9_solana_beta_settlement.so';
const old=JSON.parse(await readFile(base+'evidence/native-deposit-01/SOURCE-PINS.json','utf8'));
assert.equal(sha(await readFile(fixtureBin)).toString('hex'),old.fixture_binary);
assert.equal(sha(await readFile(elf)).toString('hex'),old['../sbf-bin/zk9_solana_beta_settlement.so']);
const bufferElf=fileURLToPath(new URL('../../results/solana-proof-buffer-v1/bin/zk9_solana_proof_buffer_lab.so',import.meta.url));
const withdrawElf=base+'sbf-bin/zk9_solana_withdraw_verifier.so';
const withdrawProgram=b58(sha(Buffer.from('ZK9 Solana beta withdrawal verifier v1')));
const sendElf=fileURLToPath(new URL('../solana-beta-spend-v1/sbf-bin/zk9_solana_beta_verifier.so',import.meta.url));
const bufferProgram=b58(sha(Buffer.from('ZK9 local proof buffer program v1'))),sendProgram=b58(sha(Buffer.from('ZK9 Solana beta context proof verifier v1')));
const runtime=JSON.parse(await readFile(base+'evidence/settlement-native-signed-02/native-publication/publisher-runtime.json','utf8'));
assert.equal(sha(await readFile(bufferElf)).toString('hex'),runtime.files.buffer_elf.sha256);
assert.equal(sha(await readFile(sendElf)).toString('hex'),runtime.files.send_elf.sha256);
assert.equal(sha(await readFile(withdrawElf)).toString('hex'),runtime.files.withdraw_elf.sha256);
const authority='HHPA65zQoNHEphZ1hrSoS62jZr76TQyj8Er8W7ge6vsy'; // public seed211, public address only
const admin=key('browser-connected-bootstrap-admin'),recipient=key('browser-connected-recipient');
const makeFixture=genesis=>JSON.parse(execFileSync(fixtureBin,[authority,genesis,b58(recipient.pub)],{encoding:'utf8',timeout:10000}));
const pins={};for(const p of [fileURLToPath(import.meta.url),fixtureBin,validator,elf,bufferElf,sendElf,withdrawElf,base+'runtime-helpers.mjs',base+'publisher/transport.mjs'])pins[p]=sha(await readFile(p)).toString('hex');
await writeFile(out+'/VALIDATOR-INPUTS.json',JSON.stringify(pins,null,2)+'\n');
let f=makeFixture(b58(Buffer.alloc(32,1))),child,ended=false,stop;
const tmp=await mkdtemp('/private/tmp/zk9-browser-connected-'),pause=ms=>new Promise(r=>setTimeout(r,ms));
const stopping=new Promise(r=>stop=r);process.once('SIGINT',stop);process.once('SIGTERM',stop);
const releaseLease=hostLease(process.stdin,stop);
async function port(){const s=net.createServer();await new Promise((r,j)=>{s.once('error',j);s.listen(0,'127.0.0.1',r);});const p=s.address().port;await new Promise(r=>s.close(r));return p;}
const rpcPort=await port(),gossip=await port(),faucet=await port(),endpoint='http://127.0.0.1:'+rpcPort+'/';
await writeFile(tmp+'/cli.yml','json_rpc_url: '+endpoint+'\nwebsocket_url: ""\nkeypair_path: '+tmp+'/unused.json\ncommitment: confirmed\n');
const accounts=[];
for(const [name,pub,hex] of [['mint',f.mint,f.mint_hex],['source',f.source,f.source_hex],['recipient',f.recipient_token,f.recipient_token_hex]]){
  const p=tmp+'/'+name+'.json',bytes=Buffer.from(hex,'hex');
  await writeFile(p,JSON.stringify({pubkey:pub,account:{lamports:40000000000,data:[bytes.toString('base64'),'base64'],owner:f.token_program,executable:false,rentEpoch:0,space:bytes.length}}));accounts.push('--account',pub,p);
}
const log=await open(out+'/validator.log','wx');let rid=0;
async function rpc(method,params=[]){const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:++rid,method,params}),signal:AbortSignal.timeout(15000)});const r=await response.json();if(r.error)throw Error(method+': '+JSON.stringify(r.error));return r.result;}
async function confirm(sig){for(let n=0;n<600;n++){const s=(await rpc('getSignatureStatuses',[[sig],{searchTransactionHistory:true}])).value[0];if(s && ['confirmed','finalized'].includes(s.confirmationStatus)){assert.equal(s.err,null);return s;}await pause(100);}throw Error('Setup confirmation timed out');}
const account=async pub=>(await rpc('getAccountInfo',[pub,{encoding:'base64',commitment:'confirmed'}])).value;
const data=a=>Buffer.from(a.data[0],'base64'),meta=(pub,signer=false,writable=false)=>({pub:typeof pub==='string'?un58(pub):pub,signer,writable});
async function submit(ix){const block=(await rpc('getLatestBlockhash',[{commitment:'confirmed'}])).value;const tx=signedTransaction(admin,ix,[],block.blockhash,block.lastValidBlockHeight);await confirm(await rpc('sendTransaction',[tx.raw,{encoding:'base64',preflightCommitment:'confirmed'}]));}
let ready=false;
try{
  child=spawn(validator,['--config',tmp+'/cli.yml','--ledger',tmp+'/ledger','--bind-address','127.0.0.1','--rpc-port',String(rpcPort),'--gossip-port',String(gossip),'--faucet-port',String(faucet),'--mint',b58(key('browser-unused-genesis').pub),'--upgradeable-program',f.program,elf,b58(admin.pub),'--upgradeable-program',bufferProgram,bufferElf,b58(admin.pub),'--upgradeable-program',sendProgram,sendElf,b58(admin.pub),'--upgradeable-program',withdrawProgram,withdrawElf,b58(admin.pub),...accounts,'--limit-ledger-size','1000000000','--quiet'],{stdio:['ignore',log.fd,log.fd],env:{PATH:'/usr/bin:/bin',TMPDIR:'/private/tmp',RUST_LOG:'error'}});
  child.on('exit',()=>{ended=true;});child.on('error',()=>{ended=true;});
  for(let n=0;n<180;n++){try{if(await rpc('getHealth')==='ok'){ready=true;break;}}catch{}if(ended)throw Error('Validator exited');await pause(250);}assert.ok(ready,'Validator startup timeout');
  assert.equal((await rpc('getVersion'))['solana-core'],'3.1.10');
  f=makeFixture(await rpc('getGenesisHash'));
  await confirm(await rpc('requestAirdrop',[b58(admin.pub),10000000000]));
  await confirm(await rpc('requestAirdrop',[authority,100000000000]));
  for(const pub of [f.program,bufferProgram,sendProgram,withdrawProgram]){const deployed=await account(pub),programData=data(deployed).subarray(4);
  await submit([{program:un58(deployed.owner),accounts:[meta(programData,false,true),meta(admin.pub,true)],data:u32(4)}]);}
  await submit([{program:un58(f.program),accounts:[meta(f.pool,false,true),meta(f.vault,false,true),meta(f.mint),meta(f.token_program),meta(admin.pub,true,true),meta(Buffer.alloc(32)),meta(f.empty_root_key,false,true)],data:Buffer.concat([Buffer.from([0]),un58(f.genesis)])}]);
  const pool=data(await account(f.pool)),context=Buffer.concat([pool.subarray(104,136),pool.subarray(8,40),pool.subarray(40,72)]).toString('hex');
  assert.equal(data(await account(f.recipient_token)).readBigUInt64LE(64),0n);
  const sourceBefore=data(await account(f.source)).readBigUInt64LE(64).toString();assert.equal(data(await account(f.vault)).readBigUInt64LE(64),0n);
  const config={network:{endpoint,scope:'isolated-solana-validator-synthetic-only',version:'3.1.10',genesis:f.genesis,programs:{[f.program]:pins[elf],[bufferProgram]:pins[bufferElf],[sendProgram]:pins[sendElf],[withdrawProgram]:pins[withdrawElf]}},
    context,buffer_program:bufferProgram,proof_program:sendProgram,withdraw_program:withdrawProgram,withdraw_recipient:f.recipient_wallet,recipient_token:f.recipient_token,program:f.program,pool:f.pool,vault:f.vault,source:f.source,authority,source_before_units:sourceBefore};
  await writeFile(out+'/LIVE-CONFIG.json',JSON.stringify(config,null,2)+'\n');console.log('READY '+endpoint);
  await stopping;
} finally {
  releaseLease();process.stdin.destroy();if(child && !ended)child.kill('SIGINT');
  for(let n=0;child&&!ended&&n<150;n++)await pause(100);
  await log.close();await writeFile(out+'/VALIDATOR-STOP.json',JSON.stringify({ready,validator_ended:ended,pid:child?.pid??null},null,2)+'\n');
  if(ended)await rm(tmp,{recursive:true,force:true});assert.ok(!child||ended,'Owned validator did not stop');
}
